exports.init = (params, rng) => {
  const total = params.initialTotalWater ?? 1000;
  const initVapor = params.initialVapor ?? 10;
  const ocean = Math.max(0, total - initVapor);
  const vapor = Math.max(0, Math.min(total, initVapor));
  return { ocean, vapor, cloud: 0, land: 0, total, evapRate: 0, precipRate: 0, time: 0 };
};
exports.step = (state, params, rng) => {
  const solarEnergy = params.solarEnergy ?? 0.5;
  const surfaceTemp = params.surfaceTemp ?? 20;
  const upperAirTemp = params.upperAirTemp ?? 5;
  let { ocean, vapor, cloud, land, total, evapRate, precipRate, time } = state;
  const tempFactor = Math.max(0.1, 1 + 0.04 * (surfaceTemp - 20));
  const evapPotential = solarEnergy * 0.35 * tempFactor;
  let evapAmount = evapPotential;
  const liquid = ocean + land;
  if (evapAmount > liquid) evapAmount = liquid;
  if (evapAmount < 0) evapAmount = 0;
  let oceanEvap = 0;
  let landEvap = 0;
  if (liquid > 1e-9) {
    oceanEvap = evapAmount * (ocean / liquid);
    landEvap = evapAmount - oceanEvap;
  }
  const sat = 20 * Math.exp(0.07 * upperAirTemp);
  const excess = Math.max(0, vapor - sat);
  let condAmount = excess * 0.14;
  if (condAmount > vapor) condAmount = vapor;
  let precipFactor = 0.06 + 0.06 * (1 - (upperAirTemp + 10) / 40);
  if (precipFactor < 0.02) precipFactor = 0.02;
  if (precipFactor > 0.12) precipFactor = 0.12;
  let precipAmount = cloud * precipFactor;
  if (precipAmount > cloud) precipAmount = cloud;
  let runoffAmount = land * 0.04;
  if (runoffAmount > land) runoffAmount = land;
  let newOcean = ocean - oceanEvap + precipAmount * 0.65 + runoffAmount;
  let newLand = land - landEvap + precipAmount * 0.35 - runoffAmount;
  let newVapor = vapor + evapAmount - condAmount;
  let newCloud = cloud + condAmount - precipAmount;
  newOcean = Math.max(0, newOcean);
  newLand = Math.max(0, newLand);
  newVapor = Math.max(0, newVapor);
  newCloud = Math.max(0, newCloud);
  const sum = newOcean + newLand + newVapor + newCloud;
  const diff = total - sum;
  newOcean += diff;
  const newEvapRate = evapRate * 0.88 + evapAmount * 0.12;
  const newPrecipRate = precipRate * 0.88 + precipAmount * 0.12;
  return { ocean: newOcean, vapor: newVapor, cloud: newCloud, land: newLand, total, evapRate: newEvapRate, precipRate: newPrecipRate, time: time + 1 };
};
exports.observe = (state, params) => {
  return {
    evaporationRate: state.evapRate,
    precipitationRate: state.precipRate,
    totalWater: state.ocean + state.vapor + state.cloud + state.land,
    oceanWater: state.ocean,
    vaporAmount: state.vapor,
    cloudWater: state.cloud
  };
};
exports.view = (state, params) => {
  const solarEnergy = params.solarEnergy ?? 0.5;
  const bounds = { x: 0, y: 0, w: 100, h: 60 };
  const bodies = [];
  const total = state.total;
  const oceanProp = (state.ocean + state.land) / total;
  const oceanHeight = 5 + oceanProp * 15;
  const nOceanCols = 12;
  for (let ix = 0; ix < nOceanCols; ix++) {
    const x = 8 + ix * 6.5;
    const wave = Math.sin(state.time * 0.12 + ix * 0.9) * 0.6;
    const y = oceanHeight * 0.55 + wave;
    bodies.push({ id: 'ocean-' + ix, x, y, radius: 3.4, color: '#1e90ff' });
    bodies.push({ id: 'ocean2-' + ix, x: x + 2.2, y: y * 0.45, radius: 2.6, color: '#3aa0ff' });
  }
  for (let ix = 0; ix < 6; ix++) {
    const x = 46 + ix * 5.5;
    const y = oceanHeight + 2.2 + Math.sin(ix * 0.8) * 1.2;
    bodies.push({ id: 'land-' + ix, x, y, radius: 3.2, color: '#8fbc6b' });
    bodies.push({ id: 'land2-' + ix, x: x + 1, y: y - 0.8, radius: 2.4, color: '#a8d080' });
  }
  const sunX = 84;
  const sunY = 52;
  const sunRadius = 4.2 + solarEnergy * 3.8;
  const sunColor = solarEnergy > 0.65 ? '#ffdd33' : solarEnergy > 0.3 ? '#ffcc44' : '#ffbb66';
  bodies.push({ id: 'sun', x: sunX, y: sunY, radius: sunRadius, color: sunColor });
  if (solarEnergy > 0.15) {
    const rayCount = Math.round(solarEnergy * 6);
    for (let i = 0; i < rayCount; i++) {
      const angle = (i / rayCount) * Math.PI * 2 + state.time * 0.06;
      const rx = sunX + Math.cos(angle) * (sunRadius + 2.8);
      const ry = sunY + Math.sin(angle) * (sunRadius + 2.8);
      if (rx > 5 && rx < 95 && ry > 5 && ry < 58) {
        bodies.push({ id: 'ray-' + i, x: rx, y: ry, radius: 1.1, color: '#ffe680' });
      }
    }
  }
  const vaporCount = Math.min(28, Math.max(0, Math.round(state.vapor / 10 + state.evapRate * 28)));
  for (let i = 0; i < vaporCount; i++) {
    const baseX = 10 + (i * 13.7 % 72);
    const drift = Math.sin(state.time * 0.08 + i * 1.1) * 1.6;
    const x = baseX + drift;
    const cycle = (state.time * 0.45 + i * 7) % 24;
    const y = oceanHeight + 2 + cycle;
    if (y < 36 && x > 6 && x < 94) {
      const col = state.evapRate > 0.02 ? '#b8e6f5' : '#c8dde8';
      bodies.push({ id: 'vapor-' + i, x, y, radius: 1.5, color: col });
    }
  }
  const nCloudBodies = Math.min(20, Math.max(0, Math.round(state.cloud * 0.9)));
  for (let i = 0; i < nCloudBodies; i++) {
    const baseX = 22 + (i * 11.3 % 58);
    const baseY = 39 + (i % 3) * 2.6;
    const x = baseX + Math.sin(state.time * 0.025 + i * 0.7) * 2.2;
    const y = baseY + Math.sin(state.time * 0.03 + i) * 0.8;
    const r = 2.6 + (state.cloud / 35) * 1.4 + (i % 2) * 0.4;
    const col = state.cloud > 25 ? '#e8e8e8' : '#ffffff';
    bodies.push({ id: 'cloud-' + i, x, y, radius: r, color: col });
    if (i % 2 === 0) {
      bodies.push({ id: 'cloudpuff-' + i, x: x + 1.4, y: y + 0.9, radius: r * 0.75, color: '#f5f5f5' });
    }
  }
  const rainCount = Math.min(26, Math.round(state.precipRate * 38));
  for (let i = 0; i < rainCount; i++) {
    const baseX = 24 + (i * 9.7 % 56);
    const x = baseX + Math.sin(state.time * 0.12 + i) * 0.9;
    const cycle = (state.time * 1.3 + i * 5) % 27;
    const y = 38 - cycle;
    if (y > oceanHeight + 1 && y < 38 && x > 8 && x < 92) {
      bodies.push({ id: 'rain-' + i, x, y, radius: 1.3, color: '#0066cc' });
      bodies.push({ id: 'raintrail-' + i, x, y: y + 1.1, radius: 0.85, color: '#3399ff' });
    }
  }
  return { kind: 'bodies', bounds, bodies };
};
